import React, { useState, useEffect, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { useDonors } from '../contexts/DonorContext';

const DonorList = () => {
    const { donors, loading, error, fetchDonors, agentAssignments } = useDonors();
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [typeFilter, setTypeFilter] = useState('all');
    const [selectedDonors, setSelectedDonors] = useState([]);
    const [isBulkSelectActive, setIsBulkSelectActive] = useState(false);
    const [sortField, setSortField] = useState('created_at');
    const [sortOrder, setSortOrder] = useState('desc');

    useEffect(() => {
        fetchDonors();
    }, [fetchDonors]);

    const handleSearchChange = (e) => {
        setSearchTerm(e.target.value);
    };

    const handleStatusFilterChange = (e) => {
        setStatusFilter(e.target.value);
    };

    const handleTypeFilterChange = (e) => {
        setTypeFilter(e.target.value);
    };

    const toggleBulkSelect = () => {
        setIsBulkSelectActive(!isBulkSelectActive);
        setSelectedDonors([]);
    };

    const handleSort = (field) => {
        if (sortField === field) {
            setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
        } else {
            setSortField(field);
            setSortOrder('asc');
        }
    };

    const handleBulkSelectDonor = (donorId) => {
        if (selectedDonors.includes(donorId)) {
            setSelectedDonors(selectedDonors.filter(id => id !== donorId));
        } else {
            setSelectedDonors([...selectedDonors, donorId]);
        }
    };

    const filteredDonors = useMemo(() => {
        return donors.filter(donor => {
            const matchesSearch =
                (donor.firstName?.toLowerCase() || '').includes(searchTerm.toLowerCase()) ||
                (donor.lastName?.toLowerCase() || '').includes(searchTerm.toLowerCase()) ||
                (donor.whatsappNumber?.toString() || '').includes(searchTerm);

            const matchesStatus = statusFilter === 'all' || donor.status === statusFilter;
            const matchesType = typeFilter === 'all' || donor.type === typeFilter;

            return matchesSearch && matchesStatus && matchesType;
        });
    }, [donors, searchTerm, statusFilter, typeFilter]);

    const sortedDonors = useMemo(() => {
        return [...filteredDonors].sort((a, b) => {
            let aValue = a[sortField] || '';
            let bValue = b[sortField] || '';

            if (sortField === 'name') {
                aValue = `${a.firstName || ''} ${a.lastName || ''}`.trim().toLowerCase();
                bValue = `${b.firstName || ''} ${b.lastName || ''}`.trim().toLowerCase();
            } else if (sortField === 'price') {
                aValue = parseFloat(a.price || 0);
                bValue = parseFloat(b.price || 0);
            } else if (sortField === 'created_at') {
                aValue = new Date(a.createdAt || 0);
                bValue = new Date(b.createdAt || 0);
            }

            if (sortOrder === 'asc') {
                return aValue > bValue ? 1 : -1;
            } else {
                return aValue < bValue ? 1 : -1;
            }
        });
    }, [filteredDonors, sortField, sortOrder]);

    // Get count by status for showing in UI
    const statusCounts = useMemo(() => {
        return donors.reduce((acc, donor) => {
            acc[donor.status] = (acc[donor.status] || 0) + 1;
            return acc;
        }, {});
    }, [donors]);

    // Get count by type for showing in UI
    const typeCounts = useMemo(() => {
        return donors.reduce((acc, donor) => {
            acc[donor.type] = (acc[donor.type] || 0) + 1;
            return acc;
        }, {});
    }, [donors]);

    if (loading) {
        return (
            <div className="flex justify-center items-center h-64">
                <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-indigo-500"></div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 mb-5">
                <p>Error loading donors: {error}</p>
            </div>
        );
    }

    return (
        <div className="px-1">
            <h1 className="text-2xl font-bold mb-6 text-gray-800 border-b border-gray-200 pb-3">Donor List</h1>

            {/* Filters Row */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                {/* Search */}
                <div className="bg-gradient-to-br from-white to-blue-50 rounded-xl border-2 border-blue-200 shadow-sm p-4 hover:shadow-md transition-all duration-200">
                    <label className="block text-sm font-medium text-blue-700 mb-1">Search Donors</label>
                    <input
                        type="text"
                        placeholder="Name or phone number..."
                        value={searchTerm}
                        onChange={handleSearchChange}
                        className="w-full px-4 py-2 rounded-lg border-2 border-blue-200 focus:border-blue-500 focus:ring focus:ring-blue-200 focus:ring-opacity-50"
                    />
                </div>

                {/* Status Filter */}
                <div className="bg-gradient-to-br from-white to-emerald-50 rounded-xl border-2 border-emerald-200 shadow-sm p-4 hover:shadow-md transition-all duration-200">
                    <label className="block text-sm font-medium text-emerald-700 mb-1">Filter by Status</label>
                    <select
                        value={statusFilter}
                        onChange={handleStatusFilterChange}
                        className="w-full px-4 py-2 rounded-lg border-2 border-emerald-200 focus:border-emerald-500 focus:ring focus:ring-emerald-200 focus:ring-opacity-50"
                    >
                        <option value="all">All Statuses ({donors.length})</option>
                        <option value="pending">Pending ({statusCounts.pending || 0})</option>
                        <option value="sending">Processing ({statusCounts.sending || 0})</option>
                        <option value="done">Completed ({statusCounts.done || 0})</option>
                    </select>
                </div>

                {/* Type Filter */}
                <div className="bg-gradient-to-br from-white to-purple-50 rounded-xl border-2 border-purple-200 shadow-sm p-4 hover:shadow-md transition-all duration-200">
                    <label className="block text-sm font-medium text-purple-700 mb-1">Filter by Type</label>
                    <select
                        value={typeFilter}
                        onChange={handleTypeFilterChange}
                        className="w-full px-4 py-2 rounded-lg border-2 border-purple-200 focus:border-purple-500 focus:ring focus:ring-purple-200 focus:ring-opacity-50"
                    >
                        <option value="all">All Types ({donors.length})</option>
                        <option value="sheep">Sheep ({typeCounts.sheep || 0})</option>
                        <option value="cow">Cow ({typeCounts.cow || 0})</option>
                    </select>
                </div>
            </div>

            {/* Results Count and Actions */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 gap-4">
                <div className="bg-gradient-to-r from-gray-50 to-gray-100 px-4 py-2 rounded-lg border border-gray-200">
                    <p className="text-gray-700">
                        Showing <span className="font-semibold">{sortedDonors.length}</span> donors
                        {searchTerm && <span> matching "<span className="font-semibold">{searchTerm}</span>"</span>}
                    </p>
                </div>

                <div className="flex space-x-2">
                    <button
                        onClick={toggleBulkSelect}
                        className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 shadow-sm
                            ${isBulkSelectActive ?
                                'bg-red-600 hover:bg-red-700 text-white' :
                                'bg-gradient-to-r from-indigo-500 to-indigo-600 hover:from-indigo-600 hover:to-indigo-700 text-white'}`}
                    >
                        {isBulkSelectActive ? 'Cancel Selection' : 'Bulk Select'}
                    </button>

                    {selectedDonors.length > 0 && (
                        <Link
                            to="/assign-agent"
                            state={{ selectedDonorIds: selectedDonors }}
                            className="px-4 py-2 rounded-lg font-medium bg-gradient-to-r from-emerald-500 to-emerald-600 hover:from-emerald-600 hover:to-emerald-700 text-white shadow-sm transition-all duration-200"
                        >
                            Assign ({selectedDonors.length})
                        </Link>
                    )}
                </div>
            </div>

            {/* Donor Table/Grid */}
            <div className="bg-gradient-to-br from-white to-gray-50 rounded-xl border-2 border-gray-200 shadow-md overflow-hidden">
                {/* Table Header */}
                <div className="grid grid-cols-12 gap-2 p-4 bg-gradient-to-r from-gray-100 to-gray-200 border-b-2 border-gray-300 text-sm font-medium text-gray-700">
                    {isBulkSelectActive && (
                        <div className="col-span-1 flex items-center justify-center">
                            <input
                                type="checkbox"
                                className="h-4 w-4 text-indigo-600 border-2 border-gray-300 rounded"
                                onChange={() => {
                                    if (selectedDonors.length === sortedDonors.length) {
                                        setSelectedDonors([]);
                                    } else {
                                        setSelectedDonors(sortedDonors.map(d => d.id));
                                    }
                                }}
                                checked={selectedDonors.length > 0 && selectedDonors.length === sortedDonors.length}
                            />
                        </div>
                    )}

                    <div
                        className={`${isBulkSelectActive ? 'col-span-2' : 'col-span-3'} cursor-pointer hover:text-indigo-700`}
                        onClick={() => handleSort('name')}
                    >
                        Name
                        {sortField === 'name' && (
                            <span className="ml-1">
                                {sortOrder === 'asc' ? '↑' : '↓'}
                            </span>
                        )}
                    </div>

                    <div className="col-span-2">Type</div>

                    <div className="col-span-2">Status</div>

                    <div
                        className="col-span-2 cursor-pointer hover:text-indigo-700"
                        onClick={() => handleSort('price')}
                    >
                        Price
                        {sortField === 'price' && (
                            <span className="ml-1">
                                {sortOrder === 'asc' ? '↑' : '↓'}
                            </span>
                        )}
                    </div>

                    <div
                        className="col-span-2 cursor-pointer hover:text-indigo-700"
                        onClick={() => handleSort('created_at')}
                    >
                        Date
                        {sortField === 'created_at' && (
                            <span className="ml-1">
                                {sortOrder === 'asc' ? '↑' : '↓'}
                            </span>
                        )}
                    </div>

                    <div className="col-span-1">Actions</div>
                </div>

                {/* Table Body */}
                <div className="divide-y-2 divide-gray-100">
                    {sortedDonors.length === 0 ? (
                        <div className="p-8 text-center text-gray-500">
                            No donors match your search criteria
                        </div>
                    ) : (
                        sortedDonors.map(donor => (
                            <div
                                key={donor.id}
                                className="grid grid-cols-12 gap-2 p-4 items-center hover:bg-gradient-to-r hover:from-gray-50 hover:to-gray-100 transition-colors duration-150"
                            >
                                {isBulkSelectActive && (
                                    <div className="col-span-1 flex items-center justify-center">
                                        <input
                                            type="checkbox"
                                            className="h-4 w-4 text-indigo-600 border-2 border-gray-300 rounded focus:ring-indigo-500"
                                            onChange={() => handleBulkSelectDonor(donor.id)}
                                            checked={selectedDonors.includes(donor.id)}
                                        />
                                    </div>
                                )}

                                <div className={`${isBulkSelectActive ? 'col-span-2' : 'col-span-3'} font-medium text-gray-800`}>
                                    {donor.firstName} {donor.lastName}
                                </div>

                                <div className="col-span-2">
                                    {donor.type === 'sheep' ? (
                                        <span className="bg-sky-100 text-sky-800 px-2 py-1 rounded-full text-xs font-medium border border-sky-200 inline-block">
                                            Sheep
                                        </span>
                                    ) : (
                                        <span className="bg-purple-100 text-purple-800 px-2 py-1 rounded-full text-xs font-medium border border-purple-200 inline-block">
                                            Cow (1/7)
                                        </span>
                                    )}
                                </div>

                                <div className="col-span-2">
                                    {donor.status === 'pending' ? (
                                        <span className="bg-yellow-100 text-yellow-800 px-2 py-1 rounded-full text-xs font-medium border border-yellow-200 inline-block">
                                            Pending
                                        </span>
                                    ) : donor.status === 'sending' ? (
                                        <span className="bg-blue-100 text-blue-800 px-2 py-1 rounded-full text-xs font-medium border border-blue-200 inline-block">
                                            Processing
                                        </span>
                                    ) : (
                                        <span className="bg-green-100 text-green-800 px-2 py-1 rounded-full text-xs font-medium border border-green-200 inline-block">
                                            Complete
                                        </span>
                                    )}
                                </div>

                                <div className="col-span-2 font-medium">
                                    {Number(donor.price).toLocaleString()} DA
                                </div>

                                <div className="col-span-2 text-gray-600 text-sm">
                                    {new Date(donor.createdAt).toLocaleDateString()}
                                </div>

                                <div className="col-span-1">
                                    <Link
                                        to={`/donor/${donor.id}`}
                                        className="text-indigo-600 hover:text-indigo-800"
                                    >
                                        View
                                    </Link>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
};

export default DonorList;
